def _norm_key(k):
    return "".join(ch for ch in str(k).lower() if ch.isalnum())

def _extract_metric(sources, acceptable_keys, metric_label):
    acceptable = {_norm_key(k) for k in acceptable_keys}
    for src in sources:
        if isinstance(src, dict):
            for k, v in src.items():
                if _norm_key(k) in acceptable and v is not None:
                    return float(v)
    raise KeyError(f"Could not find staged value for {metric_label}; available CNY source keys: {[list(s.keys()) for s in sources if isinstance(s, dict)]}")

